 Copy & Paste the JSON below in the Request Body: 

 Plain Text {
 \"offline_order\": {
 \"number\": \"OFF-001\",
 \"currency_code\": \"USD\",
 \"order_items_attributes\": [
 {
 \"sku\": \"PROD-001\",
 \"quantity\": 2,
 \"item_udfs_attributes\": {
 \"Color\": \"Red\",
 \"Size\": \"Large\",
 \"Material\": \"Cotton\",
 \"Style\": \"Casual\",
 \"Pattern\": \"Striped\",
 \"Design\": \"Flowers\",
 \"Embroidery\": \"Yes\"
 }
 }
 ]
 }
 }

